<template>
  <section class="neural-lab" aria-labelledby="neural-lab-title">
    <div class="lab-heading">
      <div><span class="eyebrow">INTERACTIVE / MLP-01</span><h2 id="neural-lab-title">让公式穿过一张真实的网络</h2><p>拖动输入，观察激活值、权重和误差如何在前向与反向传播中流动。</p></div>
      <div class="lab-status"><i></i> CLIENT-SIDE SIMULATION</div>
    </div>
    <div class="lab-toolbar" role="group" aria-label="神经网络演示控制">
      <div class="mode-switch"><button type="button" :class="{ active: mode === 'forward' }" @click="mode = 'forward'">前向传播</button><button type="button" :class="{ active: mode === 'backward' }" @click="mode = 'backward'">反向传播</button></div>
      <label>激活函数<select v-model="activationName"><option value="sigmoid">Sigmoid</option><option value="tanh">Tanh</option><option value="relu">ReLU</option></select></label>
      <label>学习率 <output>{{ learningRate.toFixed(2) }}</output><input v-model.number="learningRate" type="range" min="0.01" max="0.8" step="0.01" /></label>
      <button type="button" class="run-button" @click="runStep">{{ mode === 'forward' ? '运行一次前向' : '执行一次更新' }}</button>
    </div>
    <div class="lab-grid">
      <div class="network-panel">
        <svg class="network-svg" viewBox="-20 0 800 330" role="img" aria-label="两层感知机网络图">
          <defs><filter id="node-glow"><feGaussianBlur stdDeviation="4" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>
          <g class="edges"><line v-for="edge in edges" :key="edge.id" :x1="edge.x1" :y1="edge.y1" :x2="edge.x2" :y2="edge.y2" :class="['edge', { active: edge.active }]" :style="{ stroke: edgeColor(edge.weight), strokeWidth: edgeWidth(edge.weight) }" /></g>
          <g v-for="node in nodes" :key="node.id" class="node" :class="{ active: node.active }" :transform="`translate(${node.x} ${node.y})`"><circle r="24" :style="{ fill: nodeFill(node.value) }" :filter="node.active ? 'url(#node-glow)' : undefined" /><text class="node-value" y="4">{{ node.value.toFixed(2) }}</text><text class="node-label" y="43">{{ node.label }}</text></g>
          <text class="layer-label" x="80" y="30">INPUT</text><text class="layer-label" x="360" y="30">HIDDEN</text><text class="layer-label" x="640" y="30">OUTPUT</text>
        </svg>
        <div class="network-legend"><span><i class="positive"></i> 正权重</span><span><i class="negative"></i> 负权重</span><span><i class="activation"></i> 激活强度</span></div>
      </div>
      <aside class="controls-panel">
        <div class="control-group"><label>x₁ <output>{{ inputOne.toFixed(2) }}</output></label><input v-model.number="inputOne" type="range" min="-1" max="1" step="0.01" /><label>x₂ <output>{{ inputTwo.toFixed(2) }}</output></label><input v-model.number="inputTwo" type="range" min="-1" max="1" step="0.01" /><label>目标值 y <output>{{ target.toFixed(2) }}</output></label><input v-model.number="target" type="range" min="0" max="1" step="0.01" /></div>
        <div class="metric-list"><div><span>预测值 ŷ</span><strong>{{ output.toFixed(3) }}</strong></div><div><span>损失 L</span><strong>{{ loss.toFixed(4) }}</strong></div><div><span>∂L / ∂w₁₁</span><strong>{{ gradient.toFixed(4) }}</strong></div></div>
        <p class="hint">{{ mode === 'forward' ? '信号从左向右：z = w · x + b，a = φ(z)。' : '误差从右向左：∂L/∂w = δ · a，w ← w − η∂L/∂w。' }}</p>
      </aside>
    </div>
    <div class="formula-row"><article><span>神经元</span><code>a = φ(w · x + b)</code><p>当前隐藏层使用 {{ activationName }}，输出为 {{ hiddenMean.toFixed(3) }}。</p></article><article><span>损失函数</span><code>L = ½(y − ŷ)²</code><p>目标 {{ target.toFixed(2) }} 与预测 {{ output.toFixed(3) }} 的距离。</p></article><article><span>更新规则</span><code>w ← w − η · ∂L/∂w</code><p>η = {{ learningRate.toFixed(2) }}，第 {{ stepCount }} 次演示。</p></article></div>
  </section>
</template>

<script setup>
import { computed, ref } from 'vue'
const mode = ref('forward'); const activationName = ref('sigmoid'); const inputOne = ref(0.72); const inputTwo = ref(-0.35); const target = ref(0.8); const learningRate = ref(0.18); const stepCount = ref(0)
const hiddenWeights = ref([[0.8, -0.65, 0.45], [0.35, 0.9, -0.55]]); const outputWeights = ref([0.6, -0.75, 0.5])
const activate = (value) => activationName.value === 'relu' ? Math.max(0, value) : activationName.value === 'tanh' ? Math.tanh(value) : 1 / (1 + Math.exp(-value))
const hidden = computed(() => hiddenWeights.value[0].map((weight, index) => activate(weight * inputOne.value + hiddenWeights.value[1][index] * inputTwo.value + [0.05, -0.1, 0.08][index])))
const output = computed(() => 1 / (1 + Math.exp(-(hidden.value.reduce((sum, value, index) => sum + value * outputWeights.value[index], 0) - 0.12))))
const loss = computed(() => 0.5 * (target.value - output.value) ** 2); const gradient = computed(() => (output.value - target.value) * output.value * (1 - output.value) * hidden.value[0]); const hiddenMean = computed(() => hidden.value.reduce((sum, value) => sum + value, 0) / hidden.value.length)
const nodes = computed(() => [{ id: 'x1', x: 80, y: 112, value: inputOne.value, label: 'x₁', active: mode.value === 'forward' }, { id: 'x2', x: 80, y: 232, value: inputTwo.value, label: 'x₂', active: mode.value === 'forward' }, ...hidden.value.map((value, index) => ({ id: `h${index}`, x: 360, y: 72 + index * 96, value, label: `h${index + 1}`, active: true })), { id: 'y', x: 640, y: 162, value: output.value, label: 'ŷ', active: mode.value === 'backward' }])
const edges = computed(() => { const list = []; hidden.value.forEach((_, index) => { list.push({ id: `x1-h${index}`, x1: 104, y1: 112, x2: 336, y2: 72 + index * 96, weight: hiddenWeights.value[0][index], active: true }); list.push({ id: `x2-h${index}`, x1: 104, y1: 232, x2: 336, y2: 72 + index * 96, weight: hiddenWeights.value[1][index], active: mode.value === 'backward' }); list.push({ id: `h${index}-y`, x1: 384, y1: 72 + index * 96, x2: 616, y2: 162, weight: outputWeights.value[index], active: true }) }); return list })
function edgeColor(weight) { return weight >= 0 ? '#eaff57' : '#ff8b8b' }; function edgeWidth(weight) { return Math.max(1.5, Math.min(6, 1.5 + Math.abs(weight) * 3)) }; function nodeFill(value) { return `rgba(182, 156, 255, ${Math.min(0.95, 0.22 + Math.abs(value) * 0.72)})` }
function runStep() { stepCount.value += 1; if (mode.value !== 'backward') return; const delta = (output.value - target.value) * output.value * (1 - output.value); outputWeights.value = outputWeights.value.map((weight, index) => weight - learningRate.value * delta * hidden.value[index]) }
</script>

<style scoped>
.neural-lab { margin: 30px 0 48px; padding: 24px; border: 1px solid var(--border); background: rgba(19,19,24,.82); box-shadow: var(--shadow-md); }.lab-heading,.lab-toolbar,.lab-grid{display:flex;gap:20px}.lab-heading{align-items:flex-start;justify-content:space-between;border-bottom:1px solid var(--border);padding-bottom:20px}.eyebrow,.lab-status,.layer-label,.network-legend,.formula-row span{color:var(--signal);font:.68rem var(--font-mono);letter-spacing:.08em}.lab-heading h2{margin:8px 0 7px;font-size:clamp(1.35rem,3vw,2rem)}.lab-heading p{color:var(--text-secondary);font-size:.9rem}.lab-status{white-space:nowrap;color:var(--text-tertiary)}.lab-status i{display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:var(--signal);box-shadow:0 0 9px var(--signal)}.lab-toolbar{padding:18px 0;align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--border)}.mode-switch{display:flex}.mode-switch button,.run-button,select{min-height:38px;border:1px solid var(--border);border-radius:3px;background:var(--bg-input);color:var(--text-secondary);padding:0 12px;cursor:pointer}.mode-switch button.active,.run-button{border-color:var(--signal);background:var(--signal-muted);color:var(--signal)}.lab-toolbar label,.control-group label{display:flex;align-items:center;gap:8px;color:var(--text-secondary);font:.72rem var(--font-mono)}.lab-toolbar output,.control-group output{color:var(--signal)}.lab-toolbar input{width:100px;accent-color:var(--signal)}.run-button{margin-left:auto;font-family:var(--font-mono)}.lab-grid{align-items:stretch}.network-panel{min-width:0;flex:1;padding:14px 0 0}.network-svg{display:block;width:100%;min-height:300px;overflow:visible}.edge{opacity:.26;transition:opacity .25s,stroke-width .25s}.edge.active{opacity:.9;stroke-dasharray:8 6;animation:flow 1.4s linear infinite}@keyframes flow{to{stroke-dashoffset:-28}}.node circle{stroke:rgba(246,243,233,.28);stroke-width:1;transition:all .25s}.node.active circle{stroke:var(--signal);stroke-width:2}.node-value{fill:var(--text-primary);font:600 11px var(--font-mono);text-anchor:middle}.node-label{fill:var(--text-tertiary);font:11px var(--font-mono);text-anchor:middle}.layer-label{text-anchor:middle}.network-legend{display:flex;flex-wrap:wrap;gap:14px;color:var(--text-tertiary);letter-spacing:0}.network-legend i{display:inline-block;width:12px;height:3px;margin-right:5px;vertical-align:middle;background:var(--signal)}.network-legend .negative{background:#ff8b8b}.network-legend .activation{width:8px;height:8px;border-radius:50%;background:var(--accent)}.controls-panel{width:230px;padding:18px;border-left:1px solid var(--border)}.control-group{display:grid;gap:8px}.control-group input{width:100%;accent-color:var(--signal)}.control-group label:not(:first-child){margin-top:8px}.metric-list{display:grid;gap:10px;margin-top:26px;padding-top:18px;border-top:1px solid var(--border)}.metric-list div{display:flex;justify-content:space-between;gap:10px;font:.75rem var(--font-mono)}.metric-list span{color:var(--text-tertiary)}.metric-list strong{color:var(--text-primary)}.hint{margin-top:20px;color:var(--text-secondary);font-size:.78rem;line-height:1.7}.formula-row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:18px}.formula-row article{padding:15px;border:1px solid var(--border);background:rgba(255,255,255,.025)}.formula-row code{display:block;margin:10px 0 6px;color:var(--text-primary);font:1rem var(--font-mono)}.formula-row p{color:var(--text-secondary);font-size:.76rem;line-height:1.6}@media(max-width:760px){.neural-lab{padding:16px}.lab-heading{flex-direction:column;gap:8px}.lab-toolbar{align-items:stretch;flex-direction:column}.run-button{margin-left:0}.lab-grid{flex-direction:column}.controls-panel{width:100%;padding:18px 0 0;border-top:1px solid var(--border);border-left:0}.formula-row{grid-template-columns:1fr}.network-svg{min-height:240px}}
.neural-lab,.lab-grid,.network-panel,.controls-panel{min-width:0;max-width:100%}.network-svg{height:auto;aspect-ratio:720/330}.control-group input{min-width:0;max-width:100%}
@media(max-width:760px){.neural-lab{overflow:hidden}.network-panel,.controls-panel,.formula-row{width:calc(100vw - 62px);max-width:calc(100vw - 62px)}.network-svg{min-height:0}.controls-panel{box-sizing:border-box}.metric-list div{width:100%;justify-content:flex-start}.metric-list strong{margin-left:16px}}
</style>
